package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the optional owner {@code email}: a blank (absent) value is left as-is, a present value
 * must be a syntactically valid address and is stored lower-cased. The normalized value is written back
 * onto the (shared) {@link OwnerFieldsDto} so {@link BuildOwner}/{@link ApplyOwner} store it and
 * {@code GET /owners/{id}} later returns it. A present-but-invalid value is rejected with a 400 by
 * {@code InvalidEmailExceptionHandler}.
 */
public class NormalizeOwnerEmail {

    public void service(@Val OwnerFieldsDto owner) throws InvalidEmailException {
        String email = owner.getEmail();
        if (EmailNormalizer.isBlank(email)) {
            return;
        }
        if (!EmailNormalizer.isValid(email)) {
            throw new InvalidEmailException(email);
        }
        owner.setEmail(EmailNormalizer.normalize(email));
    }
}
===== EmailNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

/**
 * The single definition of a valid, normalized owner email. An email is optional: a {@code null} or
 * blank value is left untouched (the owner simply has no email). When a non-blank value is present it
 * must be a syntactically valid address; the normalized form is the same address lower-cased.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
final class EmailNormalizer {

    private static final Pattern EMAIL = Pattern.compile(
            "^[A-Za-z0-9._%+\\-]+@[A-Za-z0-9.\\-]+\\.[A-Za-z]{2,}$");

    /** A blank (null/empty/whitespace) value counts as "no email supplied". */
    static boolean isBlank(String email) {
        return email == null || email.isBlank();
    }

    static boolean isValid(String email) {
        return EMAIL.matcher(email.trim()).matches();
    }

    /** Lower-case the (already validated, non-blank) address. */
    static String normalize(String email) {
        return email.trim().toLowerCase();
    }

    private EmailNormalizer() {
    }
}
===== RequireOwnerFields =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Runs after {@link ValidateOwner} in the create-owner pipeline and enforces the one rule the DTO's
 * declarative constraints cannot express: no required field may be <em>blank</em>. {@code address} and
 * {@code city} carry only {@code @Size(min = 1)} (no pattern), so a whitespace-only value passes schema
 * validation; this step rejects it with a 400 listing every offending field.
 *
 * <p>Layered on top of {@code @Valid} rather than replacing it: null/empty/pattern violations are still
 * caught upstream by {@link ValidateOwner} (consistent with {@code PUT /owners/{ownerId}}), and both
 * paths surface the offending field names in the response {@code errors} array.
 */
public class RequireOwnerFields {

    public void service(@Val OwnerFieldsDto owner) throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        if (isBlank(owner.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(owner.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(owner.getAddress())) {
            missing.add("address");
        }
        if (isBlank(owner.getCity())) {
            missing.add("city");
        }
        if (isBlank(owner.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
===== RequireUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create-owner request with a 409 (via {@code DuplicateHouseholdExceptionHandler}) when
 * another owner already shares the household — the same last name and the same address, compared
 * case-insensitively after collapsing runs of whitespace. A request that sets {@code sharesHousehold}
 * true opts out of the check and is allowed. The new owner is not persisted yet, so every match found
 * is another owner.
 */
public class RequireUniqueHousehold {

    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
            return;
        }
        HouseholdKey household = HouseholdKey.of(owner.getLastName(), owner.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (household.matches(existing)) {
                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
            }
        }
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * When a create-owner request sets {@code sharesHousehold} true, the new owner is allowed to share a
 * household with the existing owner(s) at the same address and last name (see {@link HouseholdKey}).
 * This step assigns the new owner — and every matching existing owner that does not already carry one
 * — the same stable {@code householdId}, so the whole household shares one identifier.
 *
 * <p>Requests that do not set {@code sharesHousehold} leave the owner without a household id.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        HouseholdKey household = HouseholdKey.of(owner.getLastName(), owner.getAddress());
        String householdId = household.householdId();
        owner.setHouseholdId(householdId);

        // Backfill the existing household members so the whole household shares the identifier.
        // These are pre-existing side entities, not the request's new owner, so they are saved
        // directly here rather than through the pipeline's save: step (which persists only the
        // new owner mutated above).
        for (Owner existing : ownerRepository.findAll()) {
            if (household.matches(existing) && !householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }
}
===== HouseholdKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.util.UUID;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of what makes owners share a household: the same last name and the same
 * address, compared case-insensitively after collapsing runs of whitespace. Shared by
 * {@link RequireUniqueHousehold} (which rejects an un-flagged duplicate) and {@link AssignHousehold}
 * (which links a {@code sharesHousehold} owner to the existing members), so both apply the same rule
 * and cannot drift apart.
 *
 * <p>Also owns the deterministic {@code householdId} derived from that key: joining the same household
 * always yields the same value and it never changes over time.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
final class HouseholdKey {

    private final String lastName;

    private final String address;

    private HouseholdKey(String lastName, String address) {
        this.lastName = lastName;
        this.address = address;
    }

    /** The household key for the given last name and address. */
    static HouseholdKey of(String lastName, String address) {
        return new HouseholdKey(normalize(lastName), normalize(address));
    }

    /** True when the existing owner belongs to this household. */
    boolean matches(Owner owner) {
        return this.lastName.equals(normalize(owner.getLastName()))
                && this.address.equals(normalize(owner.getAddress()));
    }

    /** A stable, shared identifier derived from the normalized last name and address. */
    String householdId() {
        String key = this.lastName + "\u0000" + this.address;
        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
    }

    /** Lower-cases and collapses runs of whitespace to a single space for case- and
     *  whitespace-insensitive comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

